def in_poly_rc(r,c,poly):
    # cell centers at integer coordinates
    inside0=False
    for (r1,c1),(r2,c2) in zip(poly,poly[1:]+poly[:1]):
        if (c1>c)!=(c2>c):
            x = r1 +(c-c1)*(r2-r1)/(c2-c1)
